extends RefCounted
func execute(scene_tree: SceneTree) -> Variant:
 scene_tree.root.disable_3d = true
 scene_tree.root.size = Vector2i(1280,900)
 var main = load("res://main.tscn").instantiate()
 main.prepare_initial_world = false
 main._settings_persistent = false
 main._force_touch = true
 scene_tree.root.add_child(main)
 main.set_process(false)
 var test = load("res://tests/story_handover_input_case.gd").new()
 test.requested_disposition = &"sent_to_dev"
 var result = test.begin(main)
 scene_tree.current_scene.set_meta("story_choice_main",main)
 scene_tree.current_scene.set_meta("story_choice_case",test)
 return {"result":result,"position":main._native.get_player_position(),"support":main._native.get_support_entity_id()}

extends RefCounted
func execute(scene_tree: SceneTree) -> Variant:
 var test = scene_tree.current_scene.get_meta("story_choice_case")
 var main = scene_tree.current_scene.get_meta("story_choice_main")
 var result: Dictionary = test.result()
 for i in 32:
  if result.done or not result.failures.is_empty() or result.phase == "ari_settle":
   break
  result = test.advance()
 return {"result":result,"cue":main._story_guidance._cue_key,"disposition":main._story_guidance._handover_disposition,"receipt":main._story_guidance.handover_receipt(),"radio":main._story_radio.readback()}

extends RefCounted
